// CSS class validation — ported from johnhringiv.com's css-validator.
//
// Two checks:
//   - used-but-undefined: a class appears in Blade/JS markup but no rule defines
//     it in app.css. This is the bug-catcher (typos, a utility that was never
//     hand-authored, e.g. .floating-label or .lg:stats-horizontal).
//   - defined-but-unused: a class is defined in app.css but never referenced —
//     candidate dead CSS.
//
// Static analysis only (no browser). Classes applied purely at runtime by JS or
// generated by tom-select / flatpickr / D3 never appear in the static markup, so
// they are handled via the ignore lists in css-classes.test.js rather than a live
// DOM crawl.

import fs from 'node:fs';
import fg from 'fast-glob';
import * as csstree from 'css-tree';

/**
 * Extract every class selector defined in a CSS string via css-tree's AST, which
 * correctly skips comments/strings and unescapes Tailwind-style names
 * (`.md\:max-w-xs` -> `md:max-w-xs`).
 */
export function extractDefinedClasses(css) {
    const defined = new Set();
    const ast = csstree.parse(css, { onParseError() {} });
    csstree.walk(ast, {
        visit: 'ClassSelector',
        enter(node) {
            // css-tree keeps CSS escapes in the name (`.lg\:flex` -> `lg\:flex`),
            // but the markup uses the literal form (`lg:flex`). Strip the escaping
            // backslashes so both sides compare in the same, un-escaped form.
            defined.add(node.name.replace(/\\/g, ''));
        },
    });
    return defined;
}

// Attributes/calls that assign class names in Blade, plain HTML, and JS.
// class/className capture the FULL quoted value — quotes of the OTHER kind may
// legitimately appear inside (Blade ternaries and @error('field') use
// single-quoted literals inside double-quoted attributes) and are handled by
// classTokensFromAttrValue below. NOT covered: Blade's @class([...]) directive
// — nothing uses it today; if a future view reaches for it, its classes will be
// invisible to this validator (add a pattern here, or stick to literal
// class="..." attributes).
const CLASS_ATTR_PATTERNS = [
    /class\s*=\s*"([^"]*)"/g, // HTML/Blade double-quoted attribute
    /class\s*=\s*'([^']*)'/g, // HTML/Blade single-quoted attribute
    /className\s*=\s*"([^"]*)"/g, // JS className = "..."
    /className\s*=\s*'([^']*)'/g, // JS className = '...'
    /\.attr\(\s*["']class["']\s*,\s*["']([^"']+)["']\s*\)/g, // D3 .attr('class', '...')
    /\.classed\(\s*["']([^"']+)["']/g, // D3 .classed('...', bool)
];

/**
 * Is this whitespace-split token a real CSS class name (vs a Blade/PHP/JS
 * artifact caught inside a class="..." value)? Allows Tailwind escapes (`:` `/`
 * `.` and a leading `-`); rejects anything with template/expression characters
 * and trailing-dash concatenation prefixes (`alert-` from `alert-{{ $type }}`).
 */
function looksLikeClassToken(token) {
    if (!token || token.endsWith('-')) return false;

    // Tailwind arbitrary-value classes (w-[13px], min-h-[calc(100vh-16rem)]):
    // without the JIT no rule exists for these, so they are always bugs. Accept
    // the token here so it surfaces as used-but-undefined, instead of being
    // silently dropped by the parenthesis filter below (which is how a
    // min-h-[calc(...)] on the auth pages went unnoticed).
    if (/^-?[a-zA-Z][a-zA-Z0-9:-]*-\[[^\s{}$@<>"'`?=|&!]+\]$/.test(token)) return true;

    if (/[{}$@<>()"'`?=|&!]/.test(token)) return false;
    return /^-?[a-zA-Z_][a-zA-Z0-9_:/.-]*$/.test(token);
}

/**
 * Tokenize one captured class-attribute value into class-name candidates.
 *
 * Blade `{{ ... }}` interpolations are mined for string literals in ternary
 * RESULT position only (after `?` or `:`), so conditional classes like
 * `{{ $tab === 'sailor' ? 'tab-active' : '' }}` yield `tab-active` while the
 * compared VALUE ('sailor') is never mistaken for a class. Everything outside
 * interpolations tokenizes by whitespace — which also covers the
 * `@error('field') input-error @enderror` idiom, since `input-error` stands
 * alone once the full attribute value is captured (the directive fragments are
 * rejected by looksLikeClassToken).
 */
function classTokensFromAttrValue(value) {
    const tokens = [];

    const outsideInterpolations = value.replace(/\{\{([\s\S]*?)\}\}/g, (whole, expr) => {
        for (const literal of expr.matchAll(/[?:]\s*(?:'([^']*)'|"([^"]*)")/g)) {
            tokens.push(...(literal[1] ?? literal[2] ?? '').split(/\s+/));
        }
        return ' ';
    });
    tokens.push(...outsideInterpolations.split(/\s+/));

    return tokens.filter(looksLikeClassToken);
}

/**
 * Read every source file once, returning both the confidently-parsed class set
 * (from class="…" style attributes) and the raw concatenated text.
 */
function collectSource(baseDir, patterns) {
    const used = new Set();
    const rawParts = [];
    const files = fg.sync(patterns, { cwd: baseDir, absolute: true });

    for (const file of files) {
        const content = fs.readFileSync(file, 'utf-8');
        rawParts.push(content);
        for (const pattern of CLASS_ATTR_PATTERNS) {
            pattern.lastIndex = 0;
            let match;
            while ((match = pattern.exec(content)) !== null) {
                for (const token of classTokensFromAttrValue(match[1])) {
                    used.add(token);
                }
            }
        }
    }
    return { used, raw: rawParts.join('\n') };
}

/**
 * Scan source files for class names assigned in markup/JS.
 */
export function extractUsedClasses(baseDir, patterns) {
    return collectSource(baseDir, patterns).used;
}

/**
 * Diff the sets.
 * - usedButUndefined (the failing check): a class parsed from a class="…"
 *   attribute that no rule defines. High precision — the parser only trusts
 *   real class attributes, and inside Blade `{{ }}` interiors it reads only
 *   ternary-branch literals, so a compared value like 'sailing' is never
 *   mistaken for a class.
 * - definedButUnused (informational): a defined class whose name appears
 *   NOWHERE in the source text — not even inside a Blade ternary or @error()
 *   the attribute parser skips. Using raw-substring absence keeps this
 *   conservative (won't cry "dead" over a conditionally-applied class).
 */
export function validateCSSUsage({ css, baseDir, sourcePatterns, ignore = new Set(), ignorePrefixes = [] }) {
    const defined = extractDefinedClasses(css);
    const { used, raw } = collectSource(baseDir, sourcePatterns);

    const isIgnored = (c) => ignore.has(c) || ignorePrefixes.some((p) => c.startsWith(p));

    const usedButUndefined = [...used].filter((c) => !defined.has(c) && !isIgnored(c)).sort();
    const definedButUnused = [...defined]
        .filter((c) => !used.has(c) && !raw.includes(c) && !isIgnored(c))
        .sort();

    return {
        usedButUndefined,
        definedButUnused,
        definedCount: defined.size,
        usedCount: used.size,
    };
}
